CREATE TABLE kg_support_decisions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),claim_version_id TEXT NOT NULL REFERENCES kg_assertions(claim_version_id),assessment_ids_json TEXT NOT NULL,assessment_fingerprint TEXT NOT NULL,support TEXT NOT NULL,reviewer TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX kg_support_decision_claim ON kg_support_decisions(project_id,claim_version_id,created_at);
CREATE TABLE wiki_edit_conflicts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),page_id TEXT NOT NULL REFERENCES wiki_pages(id),base_version_id TEXT,current_version_id TEXT,proposed_json TEXT NOT NULL,author TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open',resolution_version_id TEXT,created_at TEXT NOT NULL,resolved_at TEXT);
CREATE INDEX wiki_edit_conflict_page ON wiki_edit_conflicts(project_id,page_id,state);
CREATE TABLE knowledge_maintenance_items(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,target_id TEXT NOT NULL,input_hash TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',result_json TEXT NOT NULL DEFAULT '{}',error TEXT,task_id TEXT REFERENCES tasks(id),updated_at TEXT NOT NULL,UNIQUE(project_id,kind,target_id,input_hash));
CREATE INDEX knowledge_maintenance_status ON knowledge_maintenance_items(project_id,status,updated_at);
CREATE TABLE knowledge_review_events(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),comparison_id TEXT NOT NULL REFERENCES knowledge_comparisons(id),case_id TEXT NOT NULL REFERENCES knowledge_evaluation_cases(id),variant TEXT NOT NULL,review_json TEXT NOT NULL,reviewer TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE knowledge_transfer_receipts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),source_project_id TEXT NOT NULL,package_hash TEXT NOT NULL,mapping_json TEXT NOT NULL,detail_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,package_hash));
CREATE TRIGGER support_decisions_no_update BEFORE UPDATE ON kg_support_decisions BEGIN SELECT RAISE(ABORT,'Support decisions are append only'); END;
CREATE TRIGGER support_decisions_no_delete BEFORE DELETE ON kg_support_decisions BEGIN SELECT RAISE(ABORT,'Support decisions are append only'); END;
CREATE TRIGGER knowledge_reviews_no_update BEFORE UPDATE ON knowledge_review_events BEGIN SELECT RAISE(ABORT,'Review history is append only'); END;
CREATE TRIGGER knowledge_reviews_no_delete BEFORE DELETE ON knowledge_review_events BEGIN SELECT RAISE(ABORT,'Review history is append only'); END;
